        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def idiv(a, b):
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_primary():
        typ, val = peek()
        if typ == 'num':
            advance()
            return val
        elif typ == '(':
            advance()
            v = parse_expr()
            typ2, val2 = peek()
            if typ2 != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return v
        else:
            raise ValueError(f"Unexpected token: {typ}")

    def parse_factor():
        typ, val = peek()
        neg_count = 0
        while typ == '-':
            neg_count += 1
            advance()
            typ, val = peek()
        result = parse_primary()
        if neg_count % 2 == 1:
            result = -result
        return result

    def parse_term():
        result = parse_factor()
        while True:
            typ, val = peek()
            if typ == '*':
                advance()
                rhs = parse_factor()
                result = result * rhs
            elif typ == '/':
                advance()
                rhs = parse_factor()
                result = idiv(result, rhs)
            else:
                break
        return result

    def parse_expr():
        result = parse_term()
        while True:
            typ, val = peek()
            if typ == '+':
                advance()
                rhs = parse_term()
                result = result + rhs
            elif typ == '-':
                advance()
                rhs = parse_term()
                result = result - rhs
            else:
                break
        return result

    result = parse_expr()
    return result

